import { expect, test, uniqueName } from "../../fixtures";

const TAG = "@VEN-05";

test.describe("manage vendors: list, filter, search, paginate", () => {
  test("lists vendors filtered by status with a consistent total", { tag: TAG }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    // Act
    const response = await member.get("/api/vendors", {
      params: { status: "approved", limit: 100, offset: 0 },
    });

    // Assert
    expect(response.status()).toBe(200);
    const page = await response.json();
    expect(page.limit).toBe(100);
    expect(page.offset).toBe(0);
    for (const vendor of page.items) {
      expect(vendor.status).toBe("approved");
    }
    // Every approved vendor fits in one page of 100, so the total must match the items returned.
    expect(page.total).toBe(page.items.length);
  });

  test("paginates the tenant's vendors with limit and offset", { tag: TAG }, async ({ apiAs }) => {
    // Arrange: make sure the tenant has at least 25 vendors, using unique names.
    const member = await apiAs("member");
    for (let i = 0; i < 25; i++) {
      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName(`Pager Vendor ${i}`),
          category: "services",
          contact_email: `pager${i}.${Date.now().toString(36)}@northwind.test`,
        },
      });
      expect(created.status()).toBe(201);
    }

    const first = await member.get("/api/vendors", { params: { limit: 100, offset: 0 } });
    expect(first.status()).toBe(200);
    const total = (await first.json()).total as number;
    expect(total).toBeGreaterThanOrEqual(25);

    // Act
    const response = await member.get("/api/vendors", { params: { limit: 10, offset: 20 } });

    // Assert
    expect(response.status()).toBe(200);
    const page = await response.json();
    expect(page.limit).toBe(10);
    expect(page.offset).toBe(20);
    expect(page.total).toBe(total);
    expect(page.items.length).toBe(Math.min(10, Math.max(0, total - 20)));
  });

  test("searches vendors by name, ignoring case", { tag: TAG }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const name = uniqueName("Freight Partners");
    const created = await member.post("/api/vendors", {
      data: {
        name,
        category: "logistics",
        contact_email: `freight.${Date.now().toString(36)}@northwind.test`,
      },
    });
    expect(created.status()).toBe(201);
    const createdVendor = await created.json();

    // Act
    const response = await member.get("/api/vendors", {
      params: { q: "freight", limit: 100 },
    });

    // Assert
    expect(response.status()).toBe(200);
    const page = await response.json();
    expect(page.items.length).toBeGreaterThan(0);
    for (const vendor of page.items) {
      expect(vendor.name.toLowerCase()).toContain("freight");
    }
    expect(page.items.map((v: { id: string }) => v.id)).toContain(createdVendor.id);
  });
});
